from collections import deque, defaultdict

def evaluate_topological(sheet):
    indegree = {k: 0 for k in sheet}
    graph = defaultdict(list)
    values = {}

    for cell, val in sheet.items():
        if isinstance(val, int):
            values[cell] = val
        else:
            deps = val[1:].split('+')
            for dep in deps:
                graph[dep].append(cell)
                indegree[cell] += 1

    queue = deque([k for k, v in indegree.items() if v == 0])

    while queue:
        curr = queue.popleft()
        if curr not in values:
            formula = sheet[curr][1:]
            d1, d2 = formula.split('+')
            values[curr] = values[d1] + values[d2]

        for neighbor in graph[curr]:
            indegree[neighbor] -= 1
            if indegree[neighbor] == 0:
                queue.append(neighbor)

    return values

