def all_topological_sorts(tasks, dependencies):
    adj = {t: [] for t in tasks}
    indegree = {t: 0 for t in tasks}
    for u, v in dependencies:
        adj[u].append(v)
        indegree[v] += 1

    result = []
    path = []
    visited = {t: False for t in tasks}

    def backtrack():
        if len(path) == len(tasks):
            result.append(path[:])
            return
        for t in tasks:
            if indegree[t] == 0 and not visited[t]:
                visited[t] = True
                path.append(t)
                for neighbor in adj[t]:
                    indegree[neighbor] -= 1

                backtrack()

                for neighbor in adj[t]:
                    indegree[neighbor] += 1
                path.pop()
                visited[t] = False

    backtrack()
    return result

