def resolve_install_order(packages, dependencies):
    from collections import deque, defaultdict

    adj = defaultdict(list)
    indegree = {pkg: 0 for pkg in packages}

    for pre, pkg in dependencies:
        adj[pre].append(pkg)
        indegree[pkg] += 1

    queue = deque([pkg for pkg in packages if indegree[pkg] == 0])
    install_sequence = []

    while queue:
        current = queue.popleft()
        install_sequence.append(current)

        for dependent in adj[current]:
            indegree[dependent] -= 1
            if indegree[dependent] == 0:
                queue.append(dependent)

    if len(install_sequence) == len(packages):
        return install_sequence
    else:
        raise ValueError("Circular dependencies detected")
